import heapq
def kthLargestStream(k, nums, adds):
    h = list(nums)
    heapq.heapify(h)
    while len(h) > k:
        heapq.heappop(h)
    out = []
    for x in adds:
        heapq.heappush(h, x)
        if len(h) > k:
            heapq.heappop(h)
        out.append(h[0])
    return out

